    for i in range(n):
        parts = lines[i+1].split()
        t = int(parts[0])
        x = int(parts[1]) / 100000.0
        y = int(parts[2])
        operations.append((t, x, y))

    # answer[j-1] = earliest time to get j bananas (1-indexed banana count, 0-indexed array)
    answer = [-1] * m

    # current_states = set of reachable banana counts after processing operations
    current_states = {0}

    for t_idx in range(n):
        t, x, y = operations[t_idx]

        next_states = set()

        # Apply 0 to y times
        for state in current_states:
            current_state = state
            for app in range(y + 1):
                next_states.add(current_state)
                if app < y:
                    if t == 1:
                        current_state = int(ceil(current_state + x))
                    else:
                        current_state = int(ceil(current_state * x))
                    if current_state > m:
                        break

        current_states = next_states

        # Record if this is the first time we can reach banana count k
        for k in range(1, m + 1):
            if k in current_states and answer[k-1] == -1:
                answer[k-1] = t_idx + 1

    return ' '.join(map(str, answer)) + ' '

