def solution(input_str):
    import os

    # Parse input
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Build cost matrix and preference lists
    matrix = {}
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        row_dict = {}
        idx = 0
        for j in range(n):
            if j == i:
                continue
            row_dict[j] = row[idx]
            idx += 1
        matrix[i] = row_dict

    # Create preference lists (lower cost = higher priority)
    prefs = []
    for i in range(n):
        prefs.append(sorted(range(n), key=lambda j: matrix[i][j]))

    # Try multiple random approaches to find a stable matching
    # Stable matching: no two cities (i,j) are unconnected AND 
    # both i prefers j over their current partner AND j prefers i over their current partner

    trials = 0
    max_trials = 100000
    for trial in range(max_trials):
        trials += 1

        # Initialize matching
        matched = [None] * n

        # Shuffle for randomness
        import random
        random.shuffle(prefs)

        # Try a greedy matching approach
        for _ in range(1000):
            modified = False
            for i in range(n):
                for j in prefs[i]:
                    if j >= n:
                        continue
                    if matched[i] == j:
                        continue
                    if matched[j] == None and matched[i] == None:
                        # Both free, match them
                        matched[i] = j
                        matched[j] = i
                        modified = True
                        break
                    elif matched[j] == None and matched[i] is not None:
                        # j free, i matched but might improve
                        if i prefers j more than matched[i]:
                            matched[i] = j
                            matched[j] = i
                            break
                            modified = True
                if matched[i] is not None:
                    break

        # Check if this matching is stable
        stable = True
        for i in range(n):
            for j in range(i + 1, n):
                # Both unmatched or matched with different people
                mi = matched[i]
                mj = matched[j]

                if mi == j and mj == i:
                    continue  # Connected to each other

                # Check if i prefers j over current partner
                cur_i = matched[i] if matched[i] is not None else None
                cur_j = matched[j] if matched[j] is not None else None

                i_pref_j = False
                if cur_i is not None:
                    i_pref_j = prefs[i].index(j) < prefs[i].index(cur_i)
                else:
                    i_pref_j = True  # Unmatched person would prefer anyone

                j_pref_i = False
                if cur_j is not None:
                    j_pref_i = prefs[j].index(i) < prefs[j].index(cur_j)
                else:
                    j_pref_i = True

                if i_pref_j and j_pref_i:
                    stable = False
                    break

            if not stable:
                break

        if stable:
            # Build result
            res = []
            for i in range(n):
                cur = matched[i]
                if cur is not None:
                    res.append(str(cur + 1))  # 1-indexed
                else:
                    res.append("-1")
            return '\n'.join(res) + '\n'

    # No stable matching found
    return "-1\n"

