class SegmentTree:
    """Segment tree for range queries with point updates."""
    def __init__(self, size: int):
        self.n = 1
        while self.n < size:
            self.n *= 2
        self.tree = [0.0] * (2 * self.n)

    def update(self, idx: int, value: float):
        idx += self.n
        self.tree[idx] = value
        idx //= 2
        while idx > 0:
            self.tree[idx] = self.tree[2*idx+1] + self.tree[2*idx]
            idx //= 2

    def build(self, values: List[float]):
        for i, v in enumerate(values):
            self.update(i, v)
        # Fix leaves
        idx = self.n - 1
        for i in range(len(values) - 1, -1, -1):
            self.update(i, 0)
        idx = self.n - 1
        i = self.n - 1
        while i > 0:
            idx = 2*i
            self.tree[idx] = self.tree[2*idx] + self.tree[2*idx+1]
            idx //= 2

    def __init__(self, size: int):
        self.n = 1
        while self.n < size:
            self.n *= 2
        self._sum = [0.0] * (2 * self.n)

    def build(self, li: List[float]):
        for i, v in enumerate(li):
