            self._sum[i] = self._sum[2*i] + self._sum[2*i+1]
            i //= 2

    def _set(self, index: int, value: float):
        p = self.n + index
        self._sum[p] = value
        i = p >> 1
        while i:
            self._sum[i] = self._sum[2*i] + self._sum[2*i+1]
            i >>= 1

    def query_sum(self, l: int, r: int) -> float:
        s = 0.0
        i = l + self.n
        j = r + self.n
        while i < j:
