    max_edge_to_parent[0] = 0

    while stack:
        u = stack.pop()
        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                parent_node[v] = u
                max_edge_to_parent[v] = w
                stack.append(v)

    # Binary lifting
    LOG = (n - 1).bit_length() + 2 if n > 1 else 1
    parent_lift = [[-1] * LOG for _ in range(n)]
    edge_max = [[0] * LOG for _ in range(n)]

    for i in range(n):
        parent_lift[i][0] = parent_node[i]
        edge_max[i][0] = max_edge_to_parent[i]

    for j in range(1, LOG):
        for i in range(n):
            if parent_lift[i][j-1] != -1:
                p = parent_lift[i][j-1]
                parent_lift[i][j] = parent_lift[p][j-1]
                edge_max[i][j] = max(edge_max[i][j-1], edge_max[p][j-1])

    def query_max(u, v):
        if u == v:
            return 0

        # Bring to same depth
        if depth[u] > depth[v]:
            u1, u2 = u, v
        else:
            u1, u2 = v, u

        diff = depth[u1] - depth[u2]
        max_val = 0

        for j in range(LOG):
            if (diff >> j) & 1:
                max_val = max(max_val, edge_max[u1][j])
                u1 = parent_lift[u1][j]

        if u1 == u2:
            return max_val

        for j in range(LOG - 1, -1, -1):
            if parent_lift[u1][j] != parent_lift[u2][j]:
                max_val = max(max_val, edge_max[u1][j], edge_max[u2][j])
                u1 = parent_lift[u1][j]
                u2 = parent_lift[u2][j]

        max_val = max(max_val, edge_max[u1][0], edge_max[u2][0])
        return max_val

    result = []
    for u, v, w, idx in edges:
        if not edge_in_mst[idx]:
            result.append(str(query_max(u, v)))

    return '\n'.join(result)

