    lines = input_data.strip().split('\n')
    T = int(lines[0])

    output_lines = []

    for i in range(1, T + 1):
        N, K = map(int, lines[i].split())

        if K >= N:
            # If K >= N, then |P[i] - i| >= N is impossible since max diff is N-1
            output_lines.append("-1")
        elif K == 0:
            # K=0: any permutation works, use identity
            perm = ' '.join(str(j) for j in range(1, N + 1))
            output_lines.append(perm)
        else:
            # Construct lexicographically smallest permutation
            # Place values 1 to K first, then K+1 to N
            # This ensures |P[i] - i| >= K for all positions
            first_part = list(range(K + 1, N + 1))  # values K+1 to N
            second_part = list(range(1, K + 1))      # values 1 to K

            if len(first_part) != N - K:
                output_lines.append("-1")
            elif len(second_part) != K:
                output_lines.append("-1")
            else:
                perm = first_part + second_part
                perm_str = ' '.join(str(x) for x in perm)
                output_lines.append(perm_str)

    return '\n'.join(output_lines)

