from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.dist = [-1] * self.n
        self.dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v, cap, rev in self.graph[u]:
                if cap > 0 and self.dist[v] == -1:
                    self.dist[v] = self.dist[u] + 1
                    q.append(v)
        return self.dist[t] != -1

    def dfs(self, u, t, flow, ptr):
        if flow == 0 or u == t:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.dist[v] != self.dist[u] + 1 or cap == 0:
                continue
            pushed = self.dfs(v, t, min(flow, cap), ptr)
            if pushed > 0:
                self.graph[u][i][1] -= pushed
                self.graph[v][rev][1] += pushed
                return pushed
        return 0

    def dinic(self, s, t):
        max_flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                max_flow += pushed
        return max_flow


