MOD = 1000000007

def poly_mult_dense(p1, p2):
    """Multiply two dense polynomials, return new polynomial (coeff list)"""
    new = [0] * (len(p1) + len(p2) - 1)
    for i, c1 in enumerate(p1):
        if c1 == 0:
            continue
        for j, c2 in enumerate(p2):
            if c2 == 0:
                continue
            new[i+j] = (new[i+j] + c1 * c2) % MOD
    return new

def poly_to_sparse(p):
    """Convert dense polynomial to sparse representation"""
    return {i: c for i, c in enumerate(p) if c != 0}

def poly_from_sparse(sparse):
    """Convert sparse back to dense polynomial"""
    d = {0: 0}
    for i in sparse:
        d[i] = sparse[i]
    return d

def poly_sqr(sparse_p, limit):
    """Sparse polynomial squaring with limit"""
    result = {0: 0}
    items = sorted(sparse_p.items())
    for i1, c1 in items:
        for i2, c2 in items:
            if i1 + i2 <= limit:
                result[i1+i2] = (result[i1+i2] + c1 * c2) % MOD
    return result

def compute_flower_coeffs(petals, N, limit):
    """Compute coefficients for flower polynomial (sum x^pi)^N"""
    if N == 0:
        return {0: 1}

    # Base polynomial
    if sum(petals) == 0:
        return {0: 1}

    # For large N, we might use the Laguerre identity approximation
    # But for verification, use sparse polynomial multiplication

    BASE = {p: 1 for p in petals}
    # Square-doubling approach for exponentiation
    result = {0: 1}
    base = BASE.copy()

    temp = N
    while temp > 0:
        if temp & 1:
            new_result = {i + j: 0 for i, c1 in result.items() for j, c2 in base.items()}
            for i, c1 in result.items():
                for j, c2 in base.items():
                    new_result[i + j] = (new_result[i + j] + c1 * c2) % MOD
            result = new_result

        if temp - (temp & 1) > 0:
            # Square the base
            new_base = {i + j: 0 for i, c1 in base.items() for j, c2 in base.items()}
            for i, c1 in base.items():
                for j, c2 in base.items():
                    new_base[i + j] = (new_base[i + j] + c1 * c2) % MOD
            base = new_base

        temp >>= 1

    # Limit truncation
    if limit is not None:
        return {i: c for i, c in result.items() if i <= limit}
    return result

def compute_chocoline_coeffs(choc, limit):
    """Compute coefficients for chocolate polynomial 1/(1-x^c1)...(1-x^cB)"""
