def count_squares(grid):
    n, m = len(grid), len(grid[0])

    # Extract 0/1 values
    data = [[int(grid[i][j]) for j in range(m)] for i in range(n)]

    count = 0

    # Axis-aligned squares
    for k in range(2, min(n, m)):  # side length
        for r in range(n - k + 1):
            for c in range(m - k + 1):
                if is_valid_square(data, r, c, k):
                    count += 1

    # Diagonal squares
    for k in range(1, min(n, m)):  # radius
        for r in range(n):
            for c in range(m):
                if is_valid_diagonal_square(data, r, c, k):
                    count += 1

    return count

def is_valid_square(data, r, c, k):
    # Check corners
    if any(data[r + i][c + j] != 1 for i, j in [(0, 0), (0, k-1), (k-1, 0), (k-1, k-1)]):
        return False

    # Check border
    for i in range(k):
        for j in range(k):
            if i == 0 or i == k-1 or j == 0 or j == k-1:
                if data[r + i][c + j] != 1:
                    return False

    # Check interior is all 0
    for i in range(1, k - 1):
        for j in range(1, k - 1):
            if data[r + i][c + j] != 0:
                return False

    # Check no foreign 1s touching
    # Left side: positions (r, c-1), (r, c-2), ..., (2k-1, c-1)
    if any(data[r + i][c - 1] != 0 for i in range(k)):
        return False
    # Right side: positions (r, c+k), ..., (r, c+2k-1)
    if any(data[r + i][c + k] != 0 for i in range(k)):
        return False
    # Top: positions (r-1, c), ..., (r-k, c)
    if any(data[r - 1][c + j] != 0 for j in range(k)):
        return False
    # Bottom: positions (r+k, c), ..., (r+2k-1, c)
    if any(data[r + k][c + j] != 0 for j in range(k)):
        return False

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Group elements by position modulo k
    groups = {}
    for i in range(n):
        r = i % k
        if r not in groups:
            groups[r] = []
        groups[r].append(a[i])

    # For each group, sort and pair smallest with largest
    total = 0
    for r in groups:
        group = groups[r]
        group.sort()
        if len(group) >= 2:
            for i in range(len(group) // 2):
                total += abs(group[i] - group[-1 - i])

    return str(total) + '\n'

