        parent = [0] * (n + 1)
        dist[start] = 0
        q = deque([start])

        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)

