    u = max(range(1, n + 1), key=lambda x: dist1[x])
    dist2, parent = bfs(u)
    v = max(range(1, n + 1), key=lambda x: dist2[x])

    # Find center of the diameter path
    center = v
    d = dist2[v]
    if d >= 1:
        cur = parent[v]
        for _ in range(d - d // 2):
            cur = parent[cur]
            if cur == 0:
                break
        center = cur
        if d // 2 > 0:
            center = parent[parent[v]]

    # Generate shortcuts from center to all other nodes
    shortcuts = []
