    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    if n == 0:
        return "YES\n"

    # Create value to index mapping
    val_to_idx = {val: i for i, val in enumerate(p)}

    # Initialize union-find
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Build relationships using union-find
    for i in range(n):
        partner_a = a - p[i]
        if partner_a in val_to_idx:
            union(i, val_to_idx[partner_a])

        partner_b = b - p[i]
        if partner_b in val_to_idx:
            union(i, val_to_idx[partner_b])

    # Group nodes by component
    components = {}
    for i in range(n):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    result = [0] * n
    possible = True

    for nodes in components.values():
        # Check if valid for A: all nodes have their a-partner in input
        valid_A = all((a - p[node]) in val_to_idx for node in nodes)
        # Check if valid for B: all nodes have their b-partner in input
        valid_B = all((b - p[node]) in val_to_idx for node in nodes)

        if not valid_A and not valid_B:
            possible = False
            break
        elif valid_A:
            for node in nodes:
                result[node] = 0  # Set to A
        else:
            for node in nodes:
                result[node] = 1  # Set to B

    if possible:
        return "YES\n" + " ".join(map(str, result)) + " "
    else:
        return "NO"


