def solution(s):
    # Parse input
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())
    d = list(map(int, lines[1].split()))
    h = list(map(int, lines[2].split()))

    # Precompute prefix sums for distance calculation
    # prefix_d[i] = d[0] + d[1] + ... + d[i-1]
    # This represents distance from tree 1 to tree i+1 going forward
    prefix_d = [0] * (n + 2)
    for i in range(n):
        prefix_d[i + 1] = prefix_d[i] + d[i]

    def dist(x, y):
        """Compute distance from tree x to tree y going forward along the circle"""
        if x == y:
            return 0
        if x < y:
            # Path goes directly through d[x-1] to d[y-2]
            return prefix_d[y] - prefix_d[x]
        else:
            # Path wraps around: d[x-1]...d[n-1], d[0]...d[y-2]
            return prefix_d[n] - prefix_d[x] + prefix_d[y]

    results = []
    for line in lines[3:]:
        a, b = map(int, line.split())

        # Identify blocked trees
        blocked = set()
        if a <= b:
            # Blocked range [a, b]
            for i in range(a, b + 1):
                blocked.add(i)
        else:
            # Blocked range wraps: [a, n] U [1, b]
            for i in range(a, n + 1):
                blocked.add(i)
            for i in range(1, b + 1):
                blocked.add(i)

        # Identify valid (unblocked) trees
        valid_trees = [i for i in range(1, n + 1) if i not in blocked]

        # Find maximum energy among all valid tree pairs
        max_energy = 0
        for i in range(len(valid_trees)):
            for j in range(i + 1, len(valid_trees)):
                x, y = valid_trees[i], valid_trees[j]
                energy = 2 * (h[x - 1] + h[y - 1]) + dist(x, y)
                max_energy = max(max_energy, energy)

        results.append(str(max_energy))

    return '\n'.join(results)

