    adj = [[int(contacts[i][j]) for j in range(n)] for i in range(n)]

    # Memoization with depth and current counts for each employee
    # Use depth and bounds instead of full state to reduce state space
    memo = {}

    def backtrack(idx, counts, selected):
        # Base case: all employees considered
        if idx == n:
            if all(c != t for c, t in zip(counts, targets)):
                return selected
            return None

        # Pruning: if we already have a valid solution
        if all(c != t for c, t in zip(counts, targets)):
            # Need to include people to make this stable
            pass

        # State for memoization (without full counts to reduce space)
        state = (idx, counts)
        if state in memo:
            return memo[state]

        i = idx

        # Try including employee i in the party
        new_counts = counts[:]
        for j in range(n):
            if adj[i][j]:
                new_counts[j] += 1

        # Forward pruning: check if this path can lead to valid solution
        can_proceed = True
        for j in range(n):
            if new_counts[j] >= targets[j]:
                if new_counts[j] == targets[j]:
                    # Check if this can be fixed with remaining people
                    can_fix = True
                    for k in range(idx + 1, n):
                        if adj[k][j] == 1:
                            can_fix = False
                            break
                    if not can_fix:
                        can_proceed = False
                        break
                else:
                    # Over target, definitely bad
                    can_proceed = False
                    break

        if can_proceed:
            result = backtrack(idx + 1, new_counts, selected | (1 << i))
            if result is not None:
                memo[state] = result
                return result

        # Try excluding employee i from the party
        result = backtrack(idx + 1, counts, selected)
        if result is not None:
            memo[state] = result
            return result

        memo[state] = None
        return None

    # Add memoization to prevent exponential redundancy
    def backtrack_with_mem(idx, counts, selected):
        state = (idx, tuple(counts))
        if state in memo:
            return memo[state]

        if idx == n:
            if all(c != t for c, t in zip(counts, targets)):
                memo[state] = selected
                return selected
            memo[state] = None
            return None

        i = idx

        # Try including i
        new_counts = counts[:]
        for j in range(n):
            if adj[i][j]:
                new_counts[j] += 1

        result = backtrack_with_mem(idx + 1, new_counts, selected | (1 << i))
        if result is not None:
            memo[state] = result
            return result

        # Try excluding i
        result = backtrack_with_mem(idx + 1, counts, selected)
        memo[state] = result
        return result

    result = backtrack_with_mem(0, [0] * n, 0)

    if result is None:
        return "-1\n"

    # Convert result back to list of employee numbers
    selected_list = []
    for i in range(n):
        if (result >> i) & 1:
            selected_list.append(i + 1)

    result_str = f"{len(selected_list)}\n{' '.join(map(str, selected_list))}\n"
    return result_str

