    if not lines:
        return '0\n'

    first = lines[0].split()
    n, d = int(first[0]), int(first[1])

    circles = []
    for i in range(1, min(n + 1, len(lines))):
        parts = lines[i].split()
        if len(parts) >= 3:
            x, y, r = int(parts[0]), int(parts[1]), int(parts[2])
            circles.append((x, y, r))

    if not circles:
        return '0\n'

    max_hits = 0

    # For each possible hitting point distance k*d
    # Find if it can hit any circle
    max_coord = max(max(abs(cx) for cx, cy, r in circles),
                    max(abs(cy) for cx, cy, r in circles), 1)
    max_k = (max_coord + max(r for cx, cy, r in circles) + d + 1) // d + 2

    for k in range(1, max_k + 1):
        hit_dist = k * d
        hits = 0
        for cx, cy, r in circles:
            dist_center = sqrt(cx*cx + cy*cy)
            if dist_dist >= dist_center - r and hit_dist <= dist_center + r:
                hits += 1
        max_hits = max(max_hits, hits)

    return str(max_hits) + '\n'

