def solution(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    rounds = []
    for i in range(1, t + 1):
        s, e = map(int, lines[i].split())
        rounds.append((s, e))

    def compute_winning_lossing(s, e):
        """Returns (can_leewin, can_leelose) for a single round."""
        memo = {}

        def is_current_player_win(current_s, round_e):
            key = (current_s, round_e)
            if key in memo:
                return memo[key]

            # If both moves exceed e, current player has no valid moves -> loses
            if 2 * current_s > round_e and current_s + 1 > round_e:
                memo[key] = False
                return False

            can_force_loss = False

            # Check move 2*current_s (if valid)
            if 2 * current_s <= round_e:
                # If opponent loses from 2*current_s, current player wins
                if not is_current_player_win(2 * current_s, round_e):
                    can_force_loss = True

            # Check move current_s+1 (if valid)
            if not can_force_loss and current_s + 1 <= round_e:
                # If opponent loses from current_s+1, current player wins
                if not is_current_player_win(current_s + 1, round_e):
                    can_force_loss = True

            # Current player wins if they can force opponent into losing state
            memo[key] = can_force_loss
            return can_force_loss

        can_leewin = is_current_player_win(s, rounds[0][1])

        # For can_leelose: Lee loses if all his valid moves lead to Ice Bear winning
        # This happens when starting state is in a losing region
        # (Note: in actual competitive game theory, "can lose" means the position is losing)
        can_leelose = not is_current_player_win(s, rounds[0][1])

        return can_leewin, can_leelose

    results = []

    for s, e in rounds:
        can_leewin, can_leelose = compute_winning_lossing(s, e)
        results.append((can_leewin, can_leelose))

    return ' '.join(str(r[0]) for r in results) + ' ' + ' '.join(str(r[1]) for r in results)

