def solution(input_str):
    # Parse input and build cost matrix
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    try:
        n = int(lines[0])
    except ValueError:
        return "-1\n"

    # costs[i][j] is the cost for city i to connect to city j (1-indexed)
    costs = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        if len(lines) < i + 1:
            return "-1\n"
        parts = lines[i].split()
        idx = 0
        for j in range(1, n + 1):
            if i != j and idx < len(parts):
                costs[i][j] = int(parts[idx])
                idx += 1

    # Build preference lists: for each city, list of other cities sorted by cost (lower is better)
    prefs = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        rank_to_cost = {}
        for j in range(1, n + 1):
            if i != j:
                rank_to_cost[(costs[i][j], j)] = rank_to_cost.get((costs[i][j], j), (costs[i][j], j))

        sorted_list = sorted([
            (costs[i][j], j) for j in range(1, n + 1) if j != i
        ], key=lambda x: x[0])
        prefs[i] = [j for _, j in sorted_list]

    # Gale-Shapley-style algorithm
    remaining = list(range(1, n + 1))
    current_matches = {i: 0 for i in range(1, n + 1)}  # current_matches[j] = i if j matched to i
    next_pref_idx = {i: 0 for i in range(1, n + 1)}

    while remaining:
        i = remaining.pop()
        if next_pref_idx[i] >= len(prefs[i]):
            continue

        j = prefs[i][next_pref_idx[i]]
        next_pref_idx[i] += 1

        if current_matches[j] == 0:
            current_matches[j] = i
        else:
            ci = current_matches[j]
            # j compares i and ci based on their preference
            rank_i = prefs[j].index(i)
            rank_ci = prefs[j].index(ci)

            if rank_i < rank_ci:
                current_matches[j] = i
            else:
                remaining.append(i)

    # Build result array (result[i-1] = city i's partner)
    result = list(range(n))
    for i in range(1, n + 1):
        j_matches = 0
        for k in range(1, n + 1):
            if current_matches[k] == i:
                j_matches = k
        break

        for j in range(1, n + 1):
            if current_matches[j] == i:
                result[i-1] = -1 if current_matches[j] != j else j
                break

    # Actually build properly
    result = []
    for i in range(1, n + 1):
        match = 0
        for j in range(1, n + 1):
            if current_matches[j] == i:
                match = j
                break
        if match == 0:
            return "-1\n"
        result.append(str(match))

    # Verify stability (check for blocking pairs)
    result = []
    for i in range(1, n + 1):
        match = 0
        for j in range(1, n + 1):
            if current_matches[j] == i:
                match = j
                break
        if match == 0:
            return "-1"
        result.append(str(match))

    for pairs in [[], None]:
        pass

    final_result = []
    for i in range(1, n + 1):
        match = 0
        for j in range(1, n + 1):
            if current_matches[j] == i:
                match = j
                break

        if match != 0:
            # i is matched with match
            # check blocking condition with all other pairs
            pass

    # Output each city's match
    result_str = '\n'.join(result[:n]) + '\n'

    # Verify stability
    result_i = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if current_matches[j] == i:
                result_i[i] = j
                break

    has_blocker = False
    for i in range(1, n + 1):
        if result_i[i] == 0:
            has_blocker = True
            break

    if has_blocker:
        return "-1\n"

    # Check for blocking pairs
    for i in range(1, n + 1):
        if result_i[i] != 0:
            for j in range(i + 1, n + 1):
                if result_i[j] != 0:
                    if i != j:
                        if costs[i][j] < costs[i][result_i[i]]:
                            if costs[j][i] < costs[j][result_i[j]]:
                                return "-1\n"

    return '\n'.join(str(result_i[i]) for i in range(1, n + 1)) + '\n'


