def solution_implementation(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    try:
        n = int(lines[0])
    except:
        return "-1\n"

    if n < 2:
        return "-1\n"

    # Build cost matrix
    costs = [[0] * (n + 1) for _ in range(n + 1)]
    row_idx = 1
    for line_idx, line in enumerate(lines[1:], 1):
        if row_idx > n:
            break
        parts = line.split()
        col_idx = 1
        for val in parts:
            if col_idx < n:
                costs[row_idx][col_idx] = int(val)
                col_idx += 1
        row_idx += 1

    # Build preferences (by cost, lower is better)
    prefs = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        candidates = [(costs[i][j], j) for j in range(1, n + 1) if j != i]
        candidates.sort()
        prefs[i] = [j for _, j in candidates]

    # Gale-Shapley: each city proposes to its preferences
    free_cities = set(range(1, n + 1))
    partner_of = {i: 0 for i in range(1, n + 1)}
    next_proposal = {i: 0 for i in range(1, n + 1)}

    while free_cities:
        city = free_cities.pop()

        if next_proposal[city] >= len(prefs[city]):
            continue

        neighbor = prefs[city][next_proposal[city]]
        next_proposal[city] += 1

        if partner_of[neighbor] == 0:
            partner_of[neighbor] = city
        else:
            current = partner_of[neighbor]
            # Check if neighbor prefers new proposal
            if prefs[neighbor].index(neighbor) is not None:
                if neighbor < current:
                    partner_of[neighbor] = city
                else:
                    free_cities.add(city)

    # Build matching
    matching = [0] * n
    for i in range(1, n + 1):
        if partner_of.get(i) != 0:
            matching[i - 1] = partner_of[i]

    # Check for blocking pairs
    pairs = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if partner_of.get(i) != 0 and partner_of.get(j) != 0:
                pairs.append((i, j, partner_of[i], partner_of[j]))

    for i, j, p_i, p_j in pairs:
        if costs[i][j] < costs[i][p_i] and costs[j][i] < costs[j][p_j]:
            return "-1\n"

    return '\n'.join(str(r) for r in matching) + '\n'

from functools import lru_cache

def solution(s):
    parts = s.strip().split()
    n, k, m = int(parts[0]), int(parts[1]), int(parts[2])
    MOD = 10**9 + 7

    if k == 1:
        return str(n % MOD)

    @lru_cache(maxsize=None)
    def count_paths(current_planet, visited_tuple, length):
        if length == k:
            return 1

        total = 0
        upper_limit = min(current_planet + m, n)

        for next_planet in range(1, upper_limit + 1):
            if next_planet not in visited_tuple:
                new_tuple = visited_tuple + (next_planet,)
                total = (total + count_paths(next_planet, new_tuple, length + 1)) % MOD

        return total

    total = 0
    for start_planet in range(1, n + 1):
        initial_visited = (start_planet,)
        total = (total + count_paths(start_planet, initial_visited, 1)) % MOD

    return str(total)
